components.css:
.ds-btn { display: inline-flex; align-items: center; gap: 0.7rem; font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 600; font-size: 1rem; letter-spacing: 0.01em; color: #fff; background: var(--tt-prussian); border: 1px solid var(--tt-prussian); border-radius: 0; padding: 0.85rem 1.5rem; cursor: pointer; transition: background-color 0.25s var(--tt-ease), border-color 0.25s var(--tt-ease), transform 0.25s var(--tt-ease); }
.ds-btn:hover:not(:disabled) { background: var(--tt-prussian-deep); border-color: var(--tt-prussian-deep); transform: translateY(-1px); }
.ds-btn:hover:not(:disabled) svg { transform: translateX(3px); }
.ds-btn:active:not(:disabled) { transform: translateY(0); }
.ds-btn:disabled { background: transparent; color: var(--tt-ink-faint); border-color: var(--tt-rule-strong); cursor: not-allowed; }
.ds-btn svg { transition: transform 0.25s var(--tt-ease); }

.ds-navlink { font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 600; font-size: 0.95rem; letter-spacing: 0.01em; color: #fff; background: var(--tt-prussian); border: 1px solid var(--tt-prussian); border-radius: 0; padding: 0.5rem clamp(0.75rem, 2vw, 1.1rem); white-space: nowrap; cursor: pointer; transition: background-color 0.22s var(--tt-ease), border-color 0.22s var(--tt-ease); }
.ds-navlink--quiet { color: var(--tt-ink); background: transparent; border-color: var(--tt-rule-strong); }
.ds-navlink--quiet:hover { color: var(--tt-ink); background: transparent; border-color: var(--tt-ink); }

.ds-field { display: flex; flex-direction: column; min-width: 0; padding: 1.4rem 1.5rem 1.25rem 0; border-bottom: 1px solid var(--tt-rule-hair); }
.ds-field__label { font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.66rem; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: var(--tt-ink-faint); margin-bottom: 0.6rem; }
.ds-field__input { width: 100%; background: transparent; border: 0; border-bottom: 1px solid var(--tt-ink); border-radius: 0; padding: 0.25rem 0 0.5rem; color: var(--tt-ink); font-family: 'Martian Mono', ui-monospace, monospace; font-size: clamp(1.15rem, 1.8vw, 1.5rem); font-weight: 600; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; line-height: 1.25; transition: border-color 0.22s var(--tt-ease); }
.ds-field__input::placeholder { color: var(--tt-ink-faint); opacity: 1; }
.ds-field__input:focus { outline: none; border-bottom-color: var(--tt-prussian); border-bottom-width: 2px; }
.ds-field__input:focus-visible { outline: none; box-shadow: 0 2px 0 0 var(--tt-prussian); }
.ds-field__input[aria-invalid='true'] { border-bottom-color: var(--tt-vermilion); border-bottom-width: 2px; }
.ds-field__input::-webkit-inner-spin-button, .ds-field__input::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }

.ds-slip { background: var(--tt-paper-lift); border: 1px solid var(--tt-rule-strong); box-shadow: var(--tt-lift); padding: clamp(1.5rem, 3.5vw, 3rem); }
.ds-slip__head { display: flex; align-items: baseline; justify-content: space-between; gap: 1.5rem; flex-wrap: wrap; padding-bottom: 1.1rem; border-bottom: 1px solid var(--tt-rule-strong); }
.ds-slip__title { font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 700; font-size: clamp(1.5rem, 2.6vw, 2.1rem); letter-spacing: -0.015em; line-height: 1; margin: 0; }
.ds-slip__ref { display: flex; gap: 0.35rem; font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.68rem; letter-spacing: 0.16em; color: var(--tt-ink-faint); margin: 0; }
.ds-slip__slash { color: var(--tt-prussian); }

.ds-ledger { padding: 2rem 0; border-bottom: 1px solid var(--tt-rule); }
.ds-ledger__icon { display: inline-flex; color: var(--tt-prussian); margin-bottom: 1.1rem; }
.ds-ledger__name { font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 600; font-size: clamp(1.3rem, 2vw, 1.6rem); letter-spacing: -0.012em; line-height: 1.15; margin: 0 0 0.6rem; }
.ds-ledger__body { font-size: 1rem; line-height: 1.6; color: var(--tt-ink-soft); margin: 0; max-width: 68ch; }

.ds-run { list-style: none; padding: 0; margin: clamp(1.75rem, 3.5vw, 2.75rem) 0 0; border-top: 1px solid var(--tt-rule); }
.ds-run__step { padding: 2rem 0; border-bottom: 1px solid var(--tt-rule); }
.ds-run__n { display: block; font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.72rem; font-weight: 600; letter-spacing: 0.16em; color: var(--tt-prussian); margin-bottom: 0.9rem; }
.ds-run__name { font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 600; font-size: clamp(1.25rem, 2vw, 1.55rem); letter-spacing: -0.012em; line-height: 1.15; margin: 0 0 0.6rem; }
.ds-run__body { font-size: 1rem; line-height: 1.6; color: var(--tt-ink-soft); margin: 0; max-width: 68ch; }

.ds-map { margin: 0; }
.ds-map__svg { display: block; width: 100%; height: auto; border: 1px solid var(--tt-rule); box-shadow: var(--tt-lift); background: var(--tt-paper); }
.ds-map__caption { font-size: 0.875rem; line-height: 1.55; color: var(--tt-ink-soft); margin-top: 1rem; padding-left: 0.85rem; border-left: 1px solid var(--tt-rule-strong); max-width: 58ch; }
.ds-map__caption strong { font-weight: 600; color: var(--tt-ink); }

.ds-nav { width: 100%; max-width: var(--tt-rail); margin-inline: auto; padding: 1.4rem var(--tt-gutter) 1.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; }
.ds-nav__mark { display: flex; align-items: baseline; gap: 0.75rem; background: none; border: 0; padding: 0; cursor: pointer; color: var(--tt-ink); }
.ds-nav__wordmark { font-family: 'Barlow Semi Condensed', 'Arial Narrow', sans-serif; font-weight: 700; font-size: clamp(1.4rem, 5vw, 1.75rem); letter-spacing: -0.022em; line-height: 1; white-space: nowrap; }
.ds-nav__ref { font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.6rem; font-weight: 600; letter-spacing: 0.18em; color: var(--tt-ink-faint); }
.ds-nav__actions { display: flex; align-items: center; gap: clamp(0.5rem, 2vw, 1.25rem); flex: none; }

.ds-footer { background: var(--tt-paper-press); border-top: 1px solid var(--tt-rule-strong); }
.ds-footer__inner { padding-block: clamp(2.25rem, 4vw, 3.25rem); display: flex; flex-direction: column; gap: 1rem; }
.ds-footer__mark { display: flex; align-items: baseline; gap: 0.75rem; }
.ds-footer__ref { font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.6rem; font-weight: 600; letter-spacing: 0.18em; color: var(--tt-ink-faint); }
.ds-footer__contact { font-family: 'Martian Mono', ui-monospace, monospace; font-size: 0.82rem; color: var(--tt-prussian); text-decoration: none; border-bottom: 1px solid var(--tt-prussian-wash); align-self: flex-start; transition: border-color 0.22s var(--tt-ease); }
.ds-footer__contact:hover { border-bottom-color: var(--tt-prussian); }
.ds-footer__note { font-size: 0.8rem; line-height: 1.55; color: var(--tt-ink-soft); margin: 0; max-width: 68ch; }
